test('renderInvoiceText with full invoice data (voucher, due, payments)', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [
      { sku: products[0].sku, qty: 2, discountPercent: 0 },
    ],
  });
  const invoice = invoiceResult.value;

  const withVoucher = applyVoucher(invoice, { code: 'VOU100', amount: 2000 }).value;
  const issued = issueInvoice(withVoucher, []).value;
  const paid = recordPayment(issued, { amount: 5000, date: '2026-01-15' }).value;

  const text = renderInvoiceText(paid);

  assert.ok(text.includes('INV-2026-0001'));
  assert.ok(text.includes(firstCustomer.name));
  assert.ok(text.includes('Voucher:'));
  assert.ok(text.includes('Due:'));
  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('Total:'));
});

