  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-15',
    lines: [{ sku: products[0].sku, qty: 1, discountPercent: 0 }],
  });
  const invoice = invoiceResult.value;

  const withVoucher = applyVoucher(invoice, { code: 'TEST', amount: 5000 }).value;
