  const voucherLine = text.split('\n').find((l) => l.includes('Voucher:'));
  assert.ok(voucherLine.includes('€'));
  assert.ok(voucherLine.includes('50.00'));
});

test('renderInvoiceText with multiple payments sums total paid', () => {
  const invoiceResult = createInvoice({
    customerId: firstCustomer.id,
    issueDate: '2026-01-01',
    lines: [{ sku: products[0].sku, qty: 1, discountPercent: 0 }],
  });
