  const issued = issueInvoice(invoice, []).value;
  const paid1 = recordPayment(issued, { amount: 3000, date: '2026-01-05' }).value;
  const paid2 = recordPayment(paid1, { amount: 2000, date: '2026-01-10' }).value;

  const text = renderInvoiceText(paid2);

  assert.ok(text.includes('Paid:'));
  assert.ok(text.includes('50.00'));
});

